import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { createViewConfigurationWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await createViewConfigurationWorkflow(req.scope)
    .run({
      input: {
        "entity": "{value}",
        "configuration": {
          "visible_columns": [
            "{value}"
          ],
          "column_order": [
            "{value}"
          ]
        }
      }
    })

  res.send(result)
}

